export class HtmlReporter implements Reporter {
  readonly format = 'html';

  render(result: ScanResult): string {
    const lines: string[] = [];

    lines.push('<!DOCTYPE html>');
    lines.push('<html lang="en">');
    lines.push('<head>');
    lines.push('<meta charset="UTF-8">');
    lines.push('<meta name="viewport" content="width=device-width, initial-scale=1.0">');
    lines.push(`<title>VASO Security Scan Report — ${escapeHtml(result.timestamp)}</title>`);
    lines.push(`<style>${CSS}</style>`);
    lines.push('</head>');
    lines.push('<body>');

    // Header
    lines.push('<div class="header">');
    lines.push('<h1>VASO Security Scan Report</h1>');
    lines.push(`<div class="timestamp">${escapeHtml(result.timestamp)}</div>`);
    lines.push(`<div class="score" style="color:${gradeColor(result.totalGrade)}">${result.totalScore}/100</div>`);
    lines.push(`<div class="grade" style="color:${gradeColor(result.totalGrade)}">Grade: ${escapeHtml(result.totalGrade)}</div>`);
    if (result.agents.length > 1) {
      // Headline score is worst-case (weakest agent); show the mean as context.
      lines.push(`<div class="fleet-average">Fleet average: ${result.fleetAverage}/100</div>`);
    }
    lines.push('</div>');

    // Summary cards
    lines.push('<div class="summary-cards">');
    lines.push(this.renderCard(result.summary.critical, 'Critical', '#dc2626'));
    lines.push(this.renderCard(result.summary.warning, 'Warning', '#d97706'));
    lines.push(this.renderCard(result.summary.info, 'Info', '#2563eb'));
    lines.push(this.renderCard(result.summary.passed, 'Passed', '#16a34a'));
    lines.push('</div>');

    // Agent sections
    result.agents.forEach((agent, index) => lines.push(this.renderAgent(agent, index)));

    const host = result.hostInventory;
    if (host && (host.mcpServers.length > 0 || host.sharedMcpServers?.length || host.incomplete?.length)) {
      lines.push('<div class="agent-section">');
      lines.push('<div class="agent-header"><h2>Host</h2></div>');
      if (host.sharedMcpServers?.length) {
        lines.push('<h4>MCP servers shared by several agents</h4>');
        lines.push('<div class="agent-meta"><span>An update or compromise of one reaches every agent listed; an unpinned one can change under all of them at once.</span></div>');
        lines.push('<table><thead><tr><th>Server</th><th>Unpinned</th><th>Used by</th></tr></thead><tbody>');
        for (const g of host.sharedMcpServers) {
          const users = g.users.map(u => `${escapeHtml(sharedUserLabel(u))}: ${escapeHtml(sharedServerLabel(u))} <span class="muted">${escapeHtml(u.configFile)}</span>`).join('<br>');
          lines.push(`<tr><td class="evidence">${escapeHtml(g.key)}</td><td>${g.unpinned ? 'yes' : '—'}</td><td class="evidence">${users}</td></tr>`);
        }
        lines.push('</tbody></table>');
      }
      if (host.mcpServers.length > 0) {
        lines.push('<h4>MCP servers no detected agent owns (VS Code, a project mcp.json)</h4>');
        lines.push(this.renderMcpTable(host.mcpServers));
      }
      for (const note of host.incomplete ?? []) lines.push(`<div class="evidence">! ${escapeHtml(note)}</div>`);
      lines.push('</div>');
    }

    // OWASP coverage sections
    if (hasOwaspMcpFindings(result)) {
      lines.push(this.renderOwaspMcpCoverage(result));
    }
    if (hasOwaspAgenticFindings(result)) {
      lines.push(this.renderOwaspAgenticCoverage(result));
    }

    // Footer
    lines.push(`<div class="footer">Generated by VASO (VULNEX Agent Security Observer) ${escapeHtml(result.vasoVersion ?? VERSION)}</div>`);

    lines.push('</body>');
    lines.push('</html>');

    return lines.join('\n');
  }

  private renderCard(count: number, label: string, color: string): string {
    return `<div class="card"><div class="count" style="color:${color}">${count}</div><div class="label">${label}</div></div>`;
  }

  private renderAgent(agent: AgentScanResult, index: number): string {
    const lines: string[] = [];
    const inst = agent.installation;
    const agentLabel = inst.agentName
      ? `${escapeHtml(agent.agent)} — ${escapeHtml(inst.agentName)}`
      : escapeHtml(agent.agent);

    lines.push('<div class="agent-section">');

    // Header
    lines.push('<div class="agent-header">');
    lines.push(`<h2>${agentLabel}</h2>`);
    lines.push(`<span class="grade" style="color:${gradeColor(agent.grade)}">Score: ${agent.score}/100 (${escapeHtml(agent.grade)})</span>`);
    lines.push('</div>');

    // Meta
    const metaParts: string[] = [];
    if (inst.user) metaParts.push(`<span>User: ${escapeHtml(inst.user)}</span>`);
    if (inst.profile) metaParts.push(`<span>Profile: ${escapeHtml(inst.profile)}</span>`);
    metaParts.push(`<span>Install: ${escapeHtml(inst.installDir)}</span>`);
    lines.push(`<div class="agent-meta">${metaParts.join('')}</div>`);

    // Findings table
    const failed = agent.results.filter(r => !r.passed);
    const passed = agent.results.filter(r => r.passed);
    // Inventory findings link to their row: the first row of each id
    const anchored = new Set(failed.map(r => r.id));
    const link: FindingLinker = id => (anchored.has(id) ? `<a href="#${findingAnchor(index, id)}">${escapeHtml(id)}</a>` : escapeHtml(id));

    if (inst.inventory) lines.push(this.renderSurface(inst.inventory, link));

    if (failed.length > 0) {
      lines.push('<table>');
      lines.push('<thead><tr><th>ID</th><th>Name</th><th>Severity</th><th>Message</th><th>Evidence</th><th>Fixable</th></tr></thead>');
      lines.push('<tbody>');
      const rowIds = new Set<string>();
      for (const r of failed) {
        const first = !rowIds.has(r.id);
        rowIds.add(r.id);
        lines.push(first ? `<tr id="${findingAnchor(index, r.id)}">` : '<tr>');
        lines.push(`<td>${escapeHtml(r.id)}</td>`);
        lines.push(`<td>${escapeHtml(r.name)}</td>`);
        lines.push(`<td><span class="severity-badge" style="background:${severityColor(r.severity)}">${escapeHtml(r.severity)}</span></td>`);
        lines.push(`<td>${escapeHtml(r.message)}</td>`);
        lines.push(`<td>${this.renderEvidence(r.evidence)}</td>`);
        lines.push(`<td>${r.fixable ? escapeHtml(r.fixDescription ?? 'Yes') : '—'}</td>`);
        lines.push('</tr>');
      }
      lines.push('</tbody>');
      lines.push('</table>');
    }

    // Passed checks
    if (passed.length > 0) {
      lines.push('<div class="passed-list">');
      lines.push(`<h3>Passed (${passed.length})</h3>`);
      lines.push('<ul>');
      for (const r of passed) {
        lines.push(`<li>${escapeHtml(r.id)}: ${escapeHtml(r.name)}</li>`);
      }
      lines.push('</ul>');
      lines.push('</div>');
    }

    lines.push('</div>');
    return lines.join('\n');
  }

  /** Skills and MCP servers the agent loads; collapsed — a host can carry dozens. */
  private renderSurface(inventory: AgentInventory, link: FindingLinker): string {
    const lines: string[] = ['<details class="surface">'];
    lines.push(`<summary>Attack surface: ${escapeHtml(surfaceCounts(inventory))}</summary>`);
    const dirs = inventory.skillsDirs
      .map(d => `${escapeHtml(d.path)}${d.exists ? '' : ` <span class="muted">${escapeHtml(skillsDirNote(d))}</span>`}`)
      .join('<br>');
    if (dirs) lines.push(`<h4>Skills directories</h4><div class="evidence">${dirs}</div>`);
    if (inventory.skills.length > 0) {
      lines.push('<h4>Skills</h4>');
      lines.push('<table>');
      lines.push('<thead><tr><th>Name</th><th>Description</th><th>Path</th><th>Files</th><th>Code</th><th>Findings</th></tr></thead>');
      lines.push('<tbody>');
      for (const skill of inventory.skills) {
        const target = skill.symlinkTarget ? `<br><span class="muted">→ ${escapeHtml(skill.symlinkTarget)}</span>` : '';
        lines.push(`<tr><td>${escapeHtml(skill.name)}</td><td>${escapeHtml(skill.description ?? '')}</td>`
          + `<td class="evidence">${escapeHtml(skill.path)}${target}</td><td>${skill.files}</td><td>${skill.hasCode ? 'yes' : '—'}</td>`
          + `<td>${findingList(skill.findings, link)}</td></tr>`);
      }
      lines.push('</tbody></table>');
    }
    if (inventory.otherEntries.length > 0) {
      lines.push('<h4>Other entries (no SKILL.md)</h4>');
      lines.push(`<div class="evidence">${inventory.otherEntries.map(e => `${escapeHtml(e.path)} <span class="muted">(${e.type}, ${e.files} file${e.files === 1 ? '' : 's'})</span>${e.findings?.length ? ` — ${findingList(e.findings, link)}` : ''}`).join('<br>')}</div>`);
    }
    if (inventory.mcpServers?.length) {
      lines.push('<h4>MCP servers</h4>');
      lines.push(this.renderMcpTable(inventory.mcpServers, link));
    }
    for (const note of inventory.incomplete ?? []) lines.push(`<div class="evidence">! ${escapeHtml(note)}</div>`);
    lines.push('</details>');
    return lines.join('\n');
  }

  private renderMcpTable(servers: McpServerItem[], link: FindingLinker = escapeHtml): string {
    const lines: string[] = ['<table>'];
    lines.push('<thead><tr><th>Name</th><th>Transport</th><th>Runs / reaches</th><th>Scope</th><th>Env / headers</th><th>Config</th><th>Findings</th></tr></thead>');
    lines.push('<tbody>');
    for (const server of servers) {
      const names = [...(server.envNames ?? []), ...(server.headerNames ?? [])].join(', ');
      const off = server.disabled ? ' <span class="muted">(disabled)</span>' : '';
      lines.push(`<tr><td>${escapeHtml(server.name)}${off}</td><td>${escapeHtml(server.transport)}</td>`
        + `<td class="evidence">${escapeHtml(mcpTarget(server))}</td><td>${escapeHtml(mcpScope(server))}</td>`
        + `<td class="evidence">${escapeHtml(names) || '—'}</td><td class="evidence">${escapeHtml(server.configFile)}</td>`
        + `<td>${findingList(server.findings, link)}</td></tr>`);
    }
    lines.push('</tbody></table>');
    return lines.join('\n');
  }

  private renderOwaspAgenticCoverage(result: ScanResult): string {
    const rows = computeOwaspAgenticCoverage(result);
    const lines: string[] = ['<div class="owasp-section">'];
    lines.push('<h2>OWASP Agentic AI Top 10 Coverage</h2>');
    lines.push(
      '<div class="subtitle">How VASO\'s checks map to the OWASP Agentic AI Top 10 (precize list). ' +
        'Risks with no static signal appear as gaps.</div>',
    );
    lines.push('<table>');
    lines.push('<thead><tr><th>Risk</th><th>Title</th><th>Checks</th><th>Status</th></tr></thead>');
    lines.push('<tbody>');
    for (const row of rows) {
      lines.push('<tr>');
      lines.push(`<td class="risk-id">${escapeHtml(row.id)}</td>`);
      lines.push(`<td>${escapeHtml(row.title)}</td>`);
      lines.push(`<td class="checks">${row.checks.length > 0 ? escapeHtml(row.checks.join(', ')) : '—'}</td>`);
      lines.push(`<td>${this.agenticStatusBadge(row)}</td>`);
      lines.push('</tr>');
    }
    lines.push('</tbody></table>');
    lines.push('</div>');
    return lines.join('\n');
  }

  private agenticStatusBadge(row: OwaspAgenticCoverageRow): string {
    if (!row.inCatalog) {
      return '<span class="cov-badge cov-gap">not covered (runtime/behavioral)</span>';
    }
    if (!row.covered) {
      return '<span class="cov-badge cov-none">no findings in this scan</span>';
    }
    if (row.failed > 0) {
      return `<span class="cov-badge cov-fail">⚠️ ${row.failed} finding(s)</span>`;
    }
    return '<span class="cov-badge cov-pass">✅ pass</span>';
  }

  private renderOwaspMcpCoverage(result: ScanResult): string {
    const rows = computeOwaspMcpCoverage(result);
    const lines: string[] = ['<div class="owasp-section">'];
    lines.push('<h2>OWASP MCP Top 10 Coverage</h2>');
    lines.push(
      '<div class="subtitle">How VASO\'s MCP checks map to the OWASP MCP Top 10 (2025).</div>',
    );
    lines.push('<table>');
    lines.push('<thead><tr><th>Risk</th><th>Title</th><th>Checks</th><th>Status</th></tr></thead>');
    lines.push('<tbody>');
    for (const row of rows) {
      lines.push('<tr>');
      lines.push(`<td class="risk-id">${escapeHtml(row.id)}</td>`);
      lines.push(`<td>${escapeHtml(row.title)}</td>`);
      lines.push(`<td class="checks">${row.checks.length > 0 ? escapeHtml(row.checks.join(', ')) : '—'}</td>`);
      lines.push(`<td>${this.mcpStatusBadge(row)}</td>`);
      lines.push('</tr>');
    }
    lines.push('</tbody></table>');
    lines.push('</div>');
    return lines.join('\n');
  }

  private mcpStatusBadge(row: OwaspMcpCoverageRow): string {
    if (!row.covered) {
      return '<span class="cov-badge cov-gap">not covered (runtime/operational)</span>';
    }
    if (row.failed > 0) {
      return `<span class="cov-badge cov-fail">⚠️ ${row.failed} finding(s)</span>`;
    }
    return '<span class="cov-badge cov-pass">✅ pass</span>';
  }

  private renderEvidence(evidence?: Evidence[]): string {
    if (!evidence || evidence.length === 0) return '—';
    return evidence.map(e => {
      let text = escapeHtml(e.file);
      if (e.line) text += `:${e.line}`;
      return `<span class="evidence">${text}</span>`;
    }).join('<br>');
  }
}
